      "weight": 0.2,
      "depends_on": [
        1
      ]
    },
    {
      "id": 3,
      "claim": "Since the mass of the object remains constant, acceleration is directly proportional to the net force (a ∝ F).",
      "evidence": "In the expression a = F/m, if m is a constant, a changes linearly with F.",
      "weight": 0.3,
      "depends_on": [
        2
      ]
    },
    {
      "id": 4,
      "claim": "If the force is increased by a factor of 4, the acceleration also increases by a factor of 4.",
      "evidence": "Let F_new = 4F_old. Then a_new = (4F_old)/m = 4(F_old/m) = 4a_old.",
      "weight": 0.2,
      "depends_on": [
        3
      ]
    }
  ],
